from collections import deque

# BFS traversal (Python equivalent)
def bfs(adj, src=0):
    V = len(adj)
    visited = [False] * V
    res = []
    q = deque()
    visited[src] = True
    q.append(src)
    while q:
        curr = q.popleft()
        res.append(curr)
        for x in adj[curr]:
            if not visited[x]:
                visited[x] = True
                q.append(x)
    return res

def add_edge(adj, u, v):
    adj[u].append(v)
    adj[v].append(u)  # undirected

if __name__ == "__main__":
    V = 5
    adj = [[] for _ in range(V)]
    add_edge(adj, 1, 2); add_edge(adj, 1, 0)
    add_edge(adj, 2, 0); add_edge(adj, 2, 3); add_edge(adj, 2, 4)
    print(*bfs(adj, 0))
