Tier: 2
Source: GFG
Section: Dial's Algorithm (Optimized Dijkstra for small range weights)
Subsection: Approach

The idea is to use bucket based optimization for Dijkstra's algorithm when edge weights are small integers. Instead of using a priority queue, we create buckets for each possible distance value and process nodes in distance order by iterating through buckets sequentially.

Dial_s-Algorithm-01.webpDial_s-Algorithm-01.webp

#### Step by step approach

Create buckets equal to maximum possible distance and initialize source distance as zero in first bucket.

#### Iterate through buckets sequentially and process all nodes in current bucket
For each node, examine all adjacent nodes and calculate new distance through current node.
If shorter path found, remove node from its current bucket and place in bucket corresponding to new distance.


```cpp
#include <bits/stdc++.h>
using namespace std;
​
// Function to find Shortest Path
vector<int> shortestPath(int n, int src, vector<vector<int>> &edges) {
    vector<vector<vector<int>>> adj(n);
    int maxWeight = 0;

    // Build adjacency list and find maximum weight
    for (auto e: edges) {
        adj[e[0]].push_back({e[1], e[2]});
        adj[e[1]].push_back({e[0], e[2]});
        maxWeight = max(maxWeight, e[2]);
    }

    // Initialize distance array
    vector<int> dist(n, INT_MAX);
    dist[src] = 0;

    // Create buckets for distances
    int maxDist = (n - 1) * maxWeight;
    vector<unordered_set<int>> buckets(maxDist + 1);

    // Add source to bucket 0
    buckets[0].insert(src);

    // Process buckets in order
    for (int d = 0; d <= maxDist; d++) {

        // Process all nodes in current bucket
        while (!buckets[d].empty()) {
            int u = *buckets[d].begin();
            buckets[d].erase(buckets[d].begin());

            // Skip if we already found a better path
            if (d > dist[u]) continue;

            // Process all adjacent nodes
            for (auto& edge : adj[u]) {
                int v = edge[0];
                int weight = edge[1];
                int newDist = dist[u] + weight;

                // If shorter path found
                if (newDist < dist[v]) {

                    // Remove from old bucket if it was there
                    if (dist[v] != INT_MAX) {
                        buckets[dist[v]].erase(v);
                    }

                    // Update distance and add to new bucket
                    dist[v] = newDist;
                    buckets[newDist].insert(v);
                }
            }
        }
    }

    return dist;
}
​
int main() {
    int n = 9;
    int src = 0;
    vector<vector<int>> edges = {
        {0, 1, 4},
        {0, 7, 8},
        {1, 2, 8},
        {1, 7, 11},
        {2, 3, 7},
        {2, 8, 2},
        {3, 4, 9},
        {3, 5, 14},
        {4, 5, 10},
        {5, 6, 2},
        {6, 7, 1},
        {6, 8, 6},
        {7, 8, 7}
    };

    vector<int> res = shortestPath(n, src, edges);
    for (auto val : res) {
        cout << val << " ";
    }
    cout << endl;
    return 0;
}
```

> *Java and Python equivalents are provided below.*

```java
import java.util.*;

public class Main {
    // Adjacency List (Java equivalent)
    static List<List<Integer>> createGraph(int V, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < V; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]); // undirected
        }
        return adj;
    }

    public static void main(String[] args) {
        int V = 3;
        int[][] edges = {{0, 1}, {0, 2}, {1, 2}};
        List<List<Integer>> adj = createGraph(V, edges);

        System.out.println("Adjacency List Representation:");
        for (int i = 0; i < V; i++) {
            System.out.print(i + ": ");
            for (int j : adj.get(i)) System.out.print(j + " ");
            System.out.println();
        }
    }
}
```

```python
# Adjacency List (Python equivalent)
def create_graph(V, edges):
    adj = [[] for _ in range(V)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)  # undirected
    return adj

if __name__ == "__main__":
    V = 3
    edges = [(0, 1), (0, 2), (1, 2)]
    adj = create_graph(V, edges)
    print("Adjacency List Representation:")
    for i, neighbors in enumerate(adj):
        print(f"{i}: {' '.join(map(str, neighbors))}")
```

**Output:**
0 4 12 19 21 11 9 8 14
Time Complexity: O(V + E + W×V), where W is the maximum weight of an edge.
Space Complexity: O(V + W×V) for storing buckets and adjacency list.

