public class Main {
    // Adjacency Matrix (Java equivalent)
    static int[][] createGraph(int V, int[][] edges) {
        int[][] mat = new int[V][V];
        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            mat[u][v] = 1;
            mat[v][u] = 1; // undirected
        }
        return mat;
    }

    public static void main(String[] args) {
        int V = 3;
        int[][] edges = {{0, 1}, {0, 2}, {1, 2}};
