from collections import deque

# BFS traversal (Python equivalent)
def bfs(adj, src=0):
    V = len(adj)
    visited = [False] * V
    res = []
    q = deque()
    visited[src] = True
    q.append(src)
    while q:
        curr = q.popleft()
        res.append(curr)
        for x in adj[curr]:
            if not visited[x]:
                visited[x] = True
                q.append(x)
