        Node* n1 = node1->neighbors[i];
        Node* n2 = node2->neighbors[i];
​
        if (visited.count(n1)) {
            if (visited[n1] != n2)
                return false;
        } else {
            if (!compareGraphs(n1, n2, visited))
                return false;
        }
    }
​
    return true;
}
​
// Driver Code
