    Node* original = buildGraph();
​
    // Clone the graph
    Node* cloned = cloneGraph(original);
​
    // Compare original and cloned graph
    map<Node*, Node*> visited;
    cout << (compareGraphs(original, cloned, visited) ?
             "true" : "false") << endl;
​
    return 0;
}

