import java.util.*;

class FractionalKnapsack {
    static double fractionalKnapsack(int[] val, int[] wt, int capacity) {
        int n = val.length;
        Integer[] indices = new Integer[n];
        for (int i = 0; i < n; i++) indices[i] = i;

        // Sort indices by value/weight ratio descending
        Arrays.sort(indices, (a, b) -> Double.compare(
            (double) val[b] / wt[b], (double) val[a] / wt[a]
        ));

        double res = 0.0;
        int currentCapacity = capacity;

        for (int i : indices) {
            if (wt[i] <= currentCapacity) {
                res += val[i];
                currentCapacity -= wt[i];
            } else {
                res += ((double) val[i] / wt[i]) * currentCapacity;
                break;
            }
        }
        return res;
    }

    public static void main(String[] args) {
        int[] val = {60, 100, 120};
        int[] wt = {10, 20, 30};
        int capacity = 50;
        System.out.println(fractionalKnapsack(val, wt, capacity));
    }
}
