```java
import java.util.*;

class Dijkstra {
    static int[] dijkstra(List<List<int[]>> adj, int src) {
        int V = adj.size();
        int[] dist = new int[V];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[src] = 0;

        // Min-heap storing (distance, node)
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.offer(new int[]{0, src});

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int d = curr[0], u = curr[1];

            if (d > dist[u]) continue;

            for (int[] neighbor : adj.get(u)) {
                int v = neighbor[0], w = neighbor[1];
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.offer(new int[]{dist[v], v});
                }
            }
        }
        return dist;
    }

    public static void main(String[] args) {
        int V = 5;
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < V; i++) adj.add(new ArrayList<>());

        adj.get(0).add(new int[]{1, 4}); adj.get(0).add(new int[]{2, 8});
        adj.get(1).add(new int[]{0, 4}); adj.get(1).add(new int[]{4, 6}); adj.get(1).add(new int[]{2, 3});
        adj.get(2).add(new int[]{0, 8}); adj.get(2).add(new int[]{3, 2}); adj.get(2).add(new int[]{1, 3});
        adj.get(3).add(new int[]{2, 2}); adj.get(3).add(new int[]{4, 10});
        adj.get(4).add(new int[]{1, 6}); adj.get(4).add(new int[]{3, 10});

        System.out.println(Arrays.toString(dijkstra(adj, 0)));
    }
}
