import heapq

def dijkstra(adj, src):
    V = len(adj)
    dist = [float('inf')] * V
    dist[src] = 0
    # Min-heap storing (distance, node)
    pq = [(0, src)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    return dist

