        int s1 = find(x), s2 = find(y);
        if (s1 != s2) {
            if (rank[s1] < rank[s2])      parent[s1] = s2;
            else if (rank[s1] > rank[s2]) parent[s2] = s1;
            else { parent[s2] = s1; rank[s1]++; }
