import java.util.*;

class HuffmanCoding {
    static class Node {
        int freq, index;
        Node left, right;

        Node(int freq, int index) {
            this.freq  = freq;
            this.index = index;
        }

        Node(Node l, Node r) {
            this.freq  = l.freq + r.freq;
            this.index = Math.min(l.index, r.index);
            this.left  = l;
            this.right = r;
        }
    }

    static void preOrder(Node root, List<String> ans, String curr) {
        if (root == null) return;
        if (root.left == null && root.right == null) {
            ans.add(curr.isEmpty() ? "0" : curr);
            return;
        }
        preOrder(root.left,  ans, curr + "0");
        preOrder(root.right, ans, curr + "1");
    }

    static List<String> huffmanCodes(String s, int[] freq) {
        PriorityQueue<Node> pq = new PriorityQueue<>(
            (a, b) -> a.freq != b.freq ? a.freq - b.freq : a.index - b.index
        );
        for (int i = 0; i < s.length(); i++) pq.offer(new Node(freq[i], i));
        if (s.length() == 1) return Collections.singletonList("0");

        while (pq.size() >= 2) {
            Node l = pq.poll(), r = pq.poll();
            pq.offer(new Node(l, r));
        }

        List<String> ans = new ArrayList<>();
        preOrder(pq.poll(), ans, "");
        return ans;
    }

    public static void main(String[] args) {
        String s   = "abcdef";
        int[] freq = {5, 9, 12, 13, 16, 45};
        System.out.println(huffmanCodes(s, freq));
    }
}
```

#### Python

```python
import heapq

class Node:
    def __init__(self, freq, index, left=None, right=None):
        self.freq  = freq
        self.index = index
        self.left  = left
        self.right = right

    def __lt__(self, other):
        if self.freq != other.freq:
            return self.freq < other.freq
        return self.index < other.index

def pre_order(root, ans, curr):
    if root is None:
        return
    if root.left is None and root.right is None:
        ans.append(curr if curr else "0")
        return
    pre_order(root.left,  ans, curr + "0")
    pre_order(root.right, ans, curr + "1")

def huffman_codes(s, freq):
    n  = len(s)
    pq = [Node(freq[i], i) for i in range(n)]
    heapq.heapify(pq)

    if n == 1:
        return ["0"]

    while len(pq) >= 2:
        l = heapq.heappop(pq)
        r = heapq.heappop(pq)
