        u = min((v for v in range(V) if not mst_set[v]), key=lambda v: key[v])
        mst_set[u] = True

        for v in range(V):
            if graph[u][v] > 0 and not mst_set[v] and graph[u][v] < key[v]:
                key[v]    = graph[u][v]
                parent[v] = u

    print("Edge \tWeight")
    for i in range(1, V):
        print(f"{parent[i]} - {i}\t{graph[parent[i]][i]}")

