import java.util.*;

class MapNode {
    int key, value;
    MapNode next;
    MapNode(int k, int v) { key = k; value = v; next = null; }
}

class HashMap {
    private List<MapNode> buckets;
    private int size = 0;
    private int numBuckets;
    private final double DEFAULT_LOAD_FACTOR = 0.75;

    HashMap() {
        numBuckets = 5;
        buckets = new ArrayList<>(Collections.nCopies(numBuckets, null));
        System.out.println("HashMap created\nNumber of pairs: " + size + "\nSize: " + numBuckets);
    }

    private int getBucketInd(int key) {
        return Math.abs(Integer.hashCode(key)) % numBuckets;
    }

    void insert(int key, int value) {
        int idx = getBucketInd(key);
        MapNode head = buckets.get(idx);
        while (head != null) {
            if (head.key == key) { head.value = value; return; }
            head = head.next;
        }
        MapNode node = new MapNode(key, value);
        node.next = buckets.get(idx);
        buckets.set(idx, node);
        size++;
        double lf = (double) size / numBuckets;
        System.out.println("Pair(" + key + ", " + value + ") inserted. Load factor = " + lf);
        if (lf > DEFAULT_LOAD_FACTOR) rehash();
    }

    private void rehash() {
        System.out.println("***Rehashing Started***");
        List<MapNode> temp = buckets;
        numBuckets *= 2;
        buckets = new ArrayList<>(Collections.nCopies(numBuckets, null));
        size = 0;
        for (MapNode head : temp) {
            while (head != null) { insert(head.key, head.value); head = head.next; }
        }
        System.out.println("***Rehashing Done***. New size: " + numBuckets);
    }
}
