Subsection: Simple Chaining

This method has no concept of rehashing. It only has a fixed size array i.e. fixed number of buckets.

#### C++

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

class Hash {
    int bucketCount;
    vector<vector<int>> table;

public:
    Hash(int buckets) {
        bucketCount = buckets;
        table.resize(bucketCount);
    }

    void insert(int key) {
        int index = getHashIndex(key);
        table[index].push_back(key);
    }

    void remove(int key) {
        int index = getHashIndex(key);
        auto it = find(table[index].begin(), table[index].end(), key);
        if (it != table[index].end()) {
            table[index].erase(it);
        }
    }

    void display() {
        for (int i = 0; i < bucketCount; i++) {
            cout << i;
            for (int key : table[i]) {
                cout << " --> " << key;
            }
            cout << endl;
        }
    }

private:
    int getHashIndex(int key) {
        return key % bucketCount;
    }
};

int main() {
    vector<int> keys = {7, 18, 12, 25};
    Hash hashTable(7);
    for (int key : keys) {
        hashTable.insert(key);
    }
    hashTable.remove(12);
    hashTable.display();
    return 0;
}
```

#### Java

```java
import java.util.*;

class SimpleChaining {
    private int bucketCount;
    private List<List<Integer>> table;

    SimpleChaining(int buckets) {
        bucketCount = buckets;
        table = new ArrayList<>();
        for (int i = 0; i < bucketCount; i++) table.add(new ArrayList<>());
    }

    void insert(int key) {
        table.get(key % bucketCount).add(key);
    }

