Subsection: Chaining with Rehashing

Let's discuss another method where there is no limitation on the number of buckets. The number of buckets increases when the load factor exceeds 0.5.

We will do rehashing when the value of load factor is greater than 0.5. In rehashing, we double the size of array and add all the values again to new array (doubled size array is new array) based on hash function. Hash function should also be changed as it depends on number of buckets. Therefore, hash function behaves differently from the previous one.

#### C++

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

class Hash {
    int bucketCount;
    int numOfElements;
    vector<vector<int>> table;

public:
    Hash(int buckets) {
        bucketCount = buckets;
        numOfElements = 0;
        table.resize(bucketCount);
    }

    void insert(int key) {
        while (getLoadFactor() > 0.5) {
            rehash();
        }
        int index = getHashIndex(key);
        table[index].push_back(key);
        numOfElements++;
    }

    void remove(int key) {
        int index = getHashIndex(key);
        auto it = find(table[index].begin(), table[index].end(), key);
        if (it != table[index].end()) {
            table[index].erase(it);
            numOfElements--;
        }
    }

    void display() {
        for (int i = 0; i < bucketCount; i++) {
            cout << i;
            for (int key : table[i]) {
                cout << " --> " << key;
            }
            cout << endl;
        }
    }

private:
    int getHashIndex(int key) {
        return key % bucketCount;
    }

    float getLoadFactor() {
        return (float)numOfElements / bucketCount;
    }

    void rehash() {
        vector<vector<int>> oldTable = table;
        bucketCount *= 2;
        table.clear();
        table.resize(bucketCount);
        numOfElements = 0;
        for (const auto& bucket : oldTable) {
            for (int key : bucket) {
                insert(key);
            }
        }
    }
};

int main() {
    vector<int> keys = {15, 11, 27};
    Hash hashTable(5);
    for (int key : keys) {
        hashTable.insert(key);
    }
    hashTable.remove(11);
    hashTable.display();

    hashTable.insert(19);

    cout << "\nAfter rehashing:\n";
    hashTable.display();

    return 0;
}
```

