class ChainingWithRehash {
    private int bucketCount;
    private int numOfElements;
    private List<List<Integer>> table;

    ChainingWithRehash(int buckets) {
        bucketCount = buckets;
        numOfElements = 0;
        table = new ArrayList<>();
        for (int i = 0; i < bucketCount; i++) table.add(new ArrayList<>());
    }

    void insert(int key) {
        while (getLoadFactor() > 0.5) rehash();
        table.get(key % bucketCount).add(key);
        numOfElements++;
    }

    void remove(int key) {
        List<Integer> bucket = table.get(key % bucketCount);
        if (bucket.remove(Integer.valueOf(key))) numOfElements--;
    }

    void display() {
        for (int i = 0; i < bucketCount; i++) {
            System.out.print(i);
            for (int k : table.get(i)) System.out.print(" --> " + k);
            System.out.println();
        }
    }

    private float getLoadFactor() { return (float) numOfElements / bucketCount; }

    private void rehash() {
        List<List<Integer>> old = table;
        bucketCount *= 2;
