Topic: hashing
Subtopic: hash-functions, collision-resolution, load-factor, rehashing, open-addressing, chaining
Tier: 2
Source: GFG
Section: Linear Probing in Hash Tables
Subsection: Implementation

#### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

class HashNode {
public:
    int key, value;
    HashNode(int k, int v) {
        key = k;
        value = v;
    }
};

class HashMap {
    int capacity;
    int size;
    HashNode** arr;
    HashNode* dummy;

public:
    HashMap() {
        capacity = 20;
        size = 0;
        arr = new HashNode*[capacity];
        for (int i = 0; i < capacity; i++)
            arr[i] = NULL;
        dummy = new HashNode(-1, -1);
    }

    int hashCode(int key) {
        return key % capacity;
    }

    void rehash() {
        HashNode** oldArr = arr;
        int oldCap = capacity;
        capacity *= 2;
        size = 0;
        arr = new HashNode*[capacity];
        for (int i = 0; i < capacity; i++)
            arr[i] = NULL;
        for (int i = 0; i < oldCap; i++) {
            if (oldArr[i] != NULL && oldArr[i]->key != -1) {
                insertNode(oldArr[i]->key, oldArr[i]->value);
            }
        }
    }

    void insertNode(int key, int value) {
        if ((double)size / capacity >= 0.7)
            rehash();

        HashNode* temp = new HashNode(key, value);
        int hashIndex = hashCode(key);
        int counter = 0;

        while (arr[hashIndex] != NULL &&
               arr[hashIndex]->key != key &&
               arr[hashIndex]->key != -1) {
            if (counter++ >= capacity) return;
            hashIndex = (hashIndex + 1) % capacity;
        }

        if (arr[hashIndex] == NULL || arr[hashIndex]->key == -1)
            size++;

        arr[hashIndex] = temp;
    }

    int deleteNode(int key) {
        int hashIndex = hashCode(key);
        int counter = 0;

        while (arr[hashIndex] != NULL) {
            if (counter++ >= capacity) return -1;
            if (arr[hashIndex]->key == key) {
                int val = arr[hashIndex]->value;
                delete arr[hashIndex];
                arr[hashIndex] = dummy;
                size--;
                return val;
            }
            hashIndex = (hashIndex + 1) % capacity;
        }
        return -1;
    }

    int get(int key) {
        int hashIndex = hashCode(key);
        int counter = 0;

        while (arr[hashIndex] != NULL) {
            if (counter++ >= capacity) return -1;
            if (arr[hashIndex]->key == key)
                return arr[hashIndex]->value;
            hashIndex = (hashIndex + 1) % capacity;
        }
        return -1;
    }

    int sizeofMap() { return size; }
    bool isEmpty() { return size == 0; }

    void display() {
        for (int i = 0; i < capacity; i++) {
            if (arr[i] != NULL && arr[i]->key != -1)
                cout << arr[i]->key << " " << arr[i]->value << endl;
        }
    }
};

int main() {
    HashMap h;
    h.insertNode(1, 10);
    h.insertNode(2, 20);
    h.insertNode(3, 30);
    h.insertNode(22, 220);
    h.insertNode(42, 420);

    cout << "Hash Map Elements:\n";
    h.display();

    cout << "\nSize of map: " << h.sizeofMap() << endl;
    cout << "\nDeleting key 2 -> " << h.deleteNode(2) << endl;
    cout << "Size after deletion: " << h.sizeofMap() << endl;

    cout << "\nValue of key 3: " << h.get(3) << endl;
    cout << "Value of key 2: " << h.get(2) << endl;

    cout << "\nIs map empty? " << (h.isEmpty() ? "Yes" : "No") << endl;

    return 0;
}
```

#### Java

```java
import java.util.*;

class LinearProbingHashMap {
    private int capacity;
    private int size;
    private int[] keys;
    private int[] values;
    private static final int DELETED = Integer.MIN_VALUE;

    LinearProbingHashMap() {
        capacity = 20;
        size = 0;
        keys = new int[capacity];
        values = new int[capacity];
        Arrays.fill(keys, Integer.MAX_VALUE); // Empty marker
    }

    private int hashCode(int key) { return key % capacity; }

    private void rehash() {
        int[] oldKeys = keys;
        int[] oldValues = values;
        int oldCap = capacity;
        capacity *= 2;
        size = 0;
        keys = new int[capacity];
        values = new int[capacity];
        Arrays.fill(keys, Integer.MAX_VALUE);
        for (int i = 0; i < oldCap; i++) {
            if (oldKeys[i] != Integer.MAX_VALUE && oldKeys[i] != DELETED)
                insertNode(oldKeys[i], oldValues[i]);
        }
    }

    void insertNode(int key, int value) {
        if ((double) size / capacity >= 0.7) rehash();
        int idx = hashCode(key);
        int count = 0;
        while (keys[idx] != Integer.MAX_VALUE && keys[idx] != key && keys[idx] != DELETED) {
            if (count++ >= capacity) return;
            idx = (idx + 1) % capacity;
        }
        if (keys[idx] == Integer.MAX_VALUE || keys[idx] == DELETED) size++;
        keys[idx] = key;
        values[idx] = value;
    }

    int deleteNode(int key) {
        int idx = hashCode(key);
        int count = 0;
        while (keys[idx] != Integer.MAX_VALUE) {
            if (count++ >= capacity) return -1;
            if (keys[idx] == key) {
                int val = values[idx];
                keys[idx] = DELETED;
                size--;
                return val;
            }
            idx = (idx + 1) % capacity;
        }
        return -1;
    }

    int get(int key) {
        int idx = hashCode(key);
        int count = 0;
        while (keys[idx] != Integer.MAX_VALUE) {
            if (count++ >= capacity) return -1;
            if (keys[idx] == key) return values[idx];
            idx = (idx + 1) % capacity;
        }
        return -1;
    }

    int sizeofMap() { return size; }
    boolean isEmpty() { return size == 0; }

    void display() {
        for (int i = 0; i < capacity; i++)
            if (keys[i] != Integer.MAX_VALUE && keys[i] != DELETED)
                System.out.println(keys[i] + " " + values[i]);
    }

    public static void main(String[] args) {
        LinearProbingHashMap h = new LinearProbingHashMap();
        h.insertNode(1, 10); h.insertNode(2, 20); h.insertNode(3, 30);
        h.insertNode(22, 220); h.insertNode(42, 420);
        System.out.println("Hash Map Elements:"); h.display();
        System.out.println("\nSize: " + h.sizeofMap());
        System.out.println("\nDeleting key 2 -> " + h.deleteNode(2));
        System.out.println("Size after deletion: " + h.sizeofMap());
        System.out.println("\nValue of key 3: " + h.get(3));
        System.out.println("Value of key 2: " + h.get(2));
        System.out.println("\nIs map empty? " + (h.isEmpty() ? "Yes" : "No"));
    }
}
```

#### Python

```python
class LinearProbingHashMap:
    DELETED = object()
    EMPTY = None

    def __init__(self):
        self.capacity = 20
        self.size = 0
        self.keys = [self.EMPTY] * self.capacity
        self.values = [self.EMPTY] * self.capacity

    def _hash(self, key):
        return key % self.capacity

    def _rehash(self):
        old_keys, old_values = self.keys, self.values
        self.capacity *= 2
        self.keys = [self.EMPTY] * self.capacity
        self.values = [self.EMPTY] * self.capacity
        self.size = 0
