            } else {
                int m = nextPowerOf2(tsize);
                for (int j = 1; j <= m; j++) {
                    int t = (hv + (j + j * j) / 2) % m;
                    if (t >= tsize) continue;
                    if (table[t] == -1) { table[t] = key; break; }
                }
            }
        }
    }

    public static void main(String[] args) {
        int[] arr = {21, 10, 32, 43, 54, 65, 87, 76};
        int tsize = 11;
        int[] table = new int[tsize];
        Arrays.fill(table, -1);
        quadProbing(table, tsize, arr);
        System.out.println(Arrays.toString(table));
    }
}
```

#### Python

```python
def next_power_of_2(m):
    m -= 1
    m |= m >> 1; m |= m >> 2; m |= m >> 4; m |= m >> 8; m |= m >> 16
    return m + 1

def quad_probing_improved(table, tsize, arr):
    for key in arr:
        hv = key % tsize
        if table[hv] == -1:
            table[hv] = key
        else:
            m = next_power_of_2(tsize)
            for j in range(1, m + 1):
                t = (hv + (j + j * j) // 2) % m
                if t >= tsize:
                    continue
                if table[t] == -1:
                    table[t] = key
                    break

arr = [21, 10, 32, 43, 54, 65, 87, 76]
tsize = 11
table = [-1] * tsize
quad_probing_improved(table, tsize, arr)
print(table)
```

**Output:**
```
10 87 -1 -1 32 -1 54 65 76 43 21
```

**Time Complexity:** O(n * l), where n is the length of the array and l is the size of the hash table.
**Auxiliary Space:** O(1)

