Topic: recursion
Subtopic: introduction
Tier: 2
Source: GFG
Section: Depth First Search (DFS) for a Graph
Subsection: DFS from a Given Source of Graph

Depth First Search (DFS) starts from a given source vertex and explores one path as deeply as possible. When it reaches a vertex with no unvisited neighbors, it backtracks to the previous vertex to explore other unvisited paths. This continues until all vertices reachable from the source are visited.
In a graph, there might be loops. So we use an extra visited array to make sure that we do not process a vertex again.

#### JavaScript

```javascript
function dfsRec(adj, visited, s, res) {
    visited[s] = true;
    res.push(s);

    // Recursively visit all adjacent vertices 
    // that are not visited yet
    for (let i of adj[s]) {
        if (!visited[i]) {
            dfsRec(adj, visited, i, res);
        }
    }
}

function dfs(adj) {
    const visited = new Array(adj.length).fill(false);
    const res = [];
    dfsRec(adj, visited, 0, res);
    return res;
}

function addEdge(adj, u, v) {
    adj[u].push(v);
    adj[v].push(u);
}

let V = 5;
let adj = [];

for (let i = 0; i < V; i++)
    adj.push([]);

addEdge(adj, 1, 2);
addEdge(adj, 1, 0);
addEdge(adj, 2, 0);
addEdge(adj, 2, 3);
addEdge(adj, 2, 4);

const res = dfs(adj);

for (let i = 0; i < res.length; i++) {
    process.stdout.write(res[i] + " ");
}
```

#### C++

```cpp
#include <iostream>
#include <vector>
using namespace std;

void dfsRec(vector<vector<int>> &adj, 
vector<bool> &visited, int s, vector<int> &res) {

    visited[s] = true;

    res.push_back(s);

    // Recursively visit all adjacent vertices
    // that are not visited yet
    for (int i : adj[s])
        if (visited[i] == false)
            dfsRec(adj, visited, i, res);
}

vector<int> dfs(vector<vector<int>> &adj) {
    vector<bool> visited(adj.size(), false);
    vector<int> res;
    dfsRec(adj, visited, 0, res);
    return res;
}
void addEdge(vector<vector<int>>& adj, int u, int v) {
    adj[u].push_back(v);
    adj[v].push_back(u);
}


int main() {
    int V = 5;
    vector<vector<int>> adj(V);

    // creating adjacency list
    addEdge(adj, 1, 2);
    addEdge(adj, 1, 0);
    addEdge(adj, 2, 0);
    addEdge(adj, 2, 3);
    addEdge(adj, 2, 4);

    // Perform DFS starting from the source vertex 0
    vector<int> res = dfs(adj); 

    for (int i = 0; i < V; i++)
        cout << res[i] << " ";
}
```

#### Java

```java
import java.util.*;

public class DFS {
    static void dfsRec(List<List<Integer>> adj, boolean[] visited, int s, List<Integer> res) {
        visited[s] = true;
        res.add(s);
        for (int i : adj.get(s))
            if (!visited[i])
                dfsRec(adj, visited, i, res);
    }

    static List<Integer> dfs(List<List<Integer>> adj) {
        boolean[] visited = new boolean[adj.size()];
        List<Integer> res = new ArrayList<>();
        dfsRec(adj, visited, 0, res);
        return res;
    }

    static void addEdge(List<List<Integer>> adj, int u, int v) {
        adj.get(u).add(v);
        adj.get(v).add(u);
    }

    public static void main(String[] args) {
        int V = 5;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < V; i++) adj.add(new ArrayList<>());
        addEdge(adj, 1, 2); addEdge(adj, 1, 0);
        addEdge(adj, 2, 0); addEdge(adj, 2, 3); addEdge(adj, 2, 4);
        for (int v : dfs(adj)) System.out.print(v + " ");
    }
}
```

#### Python

```python
def dfsRec(adj, visited, s, res):
    visited[s] = True
    res.append(s)
    for i in adj[s]:
        if not visited[i]:
            dfsRec(adj, visited, i, res)

def dfs(adj):
    visited = [False] * len(adj)
    res = []
    dfsRec(adj, visited, 0, res)
    return res

def addEdge(adj, u, v):
    adj[u].append(v)
    adj[v].append(u)

V = 5
adj = [[] for _ in range(V)]
addEdge(adj, 1, 2); addEdge(adj, 1, 0)
addEdge(adj, 2, 0); addEdge(adj, 2, 3); addEdge(adj, 2, 4)
print(*dfs(adj))
```

```
Output
0 1 2 3 4
```

**Time complexity:** O(V + E), where V is the number of vertices and E is the number of edges in the graph.  
**Auxiliary Space:** O(V + E), since an extra visited array of size V is required, And stack size for recursive calls to dfsRec function.

