#### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

// Returns index of x if present, else returns -1
int search(vector<int> &arr, int x) {
    int n = arr.size();

    // initialize first three fibonacci numbers
    int a =  0, b = 1, c = 1;

    // iterate while c is smaller than n
    // c stores the smallest Fibonacci 
    // number greater than or equal to n
    while (c < n) {
        a = b;
        b = c;
        c = a + b;
    }

    // marks the eliminated range from front
    int offset = -1;

    // while there are elements to be inspected
    // Note that we compare arr[a] with x. 
    // When c becomes 1, a becomes 0
    while (c > 1) {

        // check if a is a valid location
        int i = min(offset + a, n - 1);

        // if x is greater than the value at index a,
        // cut the subarray array from offset to i 
        if (arr[i] < x) {
            c = b;
            b = a;
            a = c - b;
            offset = i;
        }

        // else if x is greater than the value at 
        // index a,cut the subarray after i+1
        else if (arr[i] > x) {
            c = a;
            b = b - a;
            a = c - b;
        }

        // else if element found, return index
        else
            return i;
    }

    // comparing the last element with x
    if (b && arr[offset + 1] == x)
        return offset + 1;

    // element not found, return -1
    return -1;
}

int main() {
    vector<int> arr = {2, 3, 4, 10, 40};
    int x = 10;
    cout << search(arr, x);
    return 0;
}
```

#### Java

```java
public class FibonacciSearch {
    static int search(int[] arr, int x) {
        int n = arr.length;
        int a = 0, b = 1, c = 1;

        while (c < n) {
            a = b;
            b = c;
            c = a + b;
        }

        int offset = -1;

        while (c > 1) {
            int i = Math.min(offset + a, n - 1);

            if (arr[i] < x) {
                c = b; b = a; a = c - b;
                offset = i;
            } else if (arr[i] > x) {
                c = a; b = b - a; a = c - b;
            } else {
                return i;
            }
        }

        if (b == 1 && arr[offset + 1] == x)
            return offset + 1;

        return -1;
    }

    public static void main(String[] args) {
        int[] arr = {2, 3, 4, 10, 40};
        System.out.println(search(arr, 10));
    }
}
```

