#### C++

```cpp
#include <iostream>
#include <cmath>
#include <vector>
using namespace std;

// Function to show the working of Meta binary search
int bsearch(vector<int> A, int key_to_search)
{
    int n = (int)A.size();
    // Set number of bits to represent largest array index
    int lg = log2(n-1)+1; 

    int pos = 0;
    for (int i = lg ; i >= 0; i--) {
        if (A[pos] == key_to_search)
            return pos;

        // Incrementally construct the
        // index of the target value
        int new_pos = pos | (1 << i);

        // find the element in one
        // direction and update position
        if ((new_pos < n) && (A[new_pos] <= key_to_search))
            pos = new_pos;
    }

    // if element found return pos otherwise -1
    return ((A[pos] == key_to_search) ? pos : -1);
}

// Driver code
int main(void)
{
    vector<int> A = { -2, 10, 100, 250, 32315 };
    cout << bsearch(A, 10) << endl;

    return 0;
}
```

#### Java

```java
public class MetaBinarySearch {
    static int bsearch(int[] A, int keyToSearch) {
        int n = A.length;
        int lg = (int)(Math.log(n - 1) / Math.log(2)) + 1;
        int pos = 0;

        for (int i = lg; i >= 0; i--) {
            if (A[pos] == keyToSearch) return pos;
            int newPos = pos | (1 << i);
            if (newPos < n && A[newPos] <= keyToSearch)
                pos = newPos;
        }

        return (A[pos] == keyToSearch) ? pos : -1;
    }

    public static void main(String[] args) {
        int[] A = {-2, 10, 100, 250, 32315};
        System.out.println(bsearch(A, 10));
    }
}
```

