            int[] curr = pq.poll();
            int x = curr[1];
            path.add(x);
            if (x == target) break;

            for (int[] neighbor : adj.get(x)) {
                if (!visited[neighbor[0]]) {
                    visited[neighbor[0]] = true;
                    pq.offer(new int[]{neighbor[1], neighbor[0]});
                }
            }
        }
        return path;
    }

    public static void main(String[] args) {
        int[][] edgeList = {
            {0,1,3},{0,2,6},{0,3,5},{1,4,9},{1,5,8},
            {2,6,12},{2,7,14},{3,8,7},{8,9,5},
            {8,10,6},{9,11,1},{9,12,10},{9,13,2}
        };
        List<Integer> path = bestFirstSearch(edgeList, 0, 9, 14);
        for (int node : path) System.out.print(node + " ");
    }
}
```

#### Python

```python
import heapq

def best_first_search(edges, src, target, n):
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))

    visited = [False] * n
    pq = [(0, src)]
    visited[src] = True
    path = []

    while pq:
        cost, x = heapq.heappop(pq)
        path.append(x)
        if x == target:
            break
        for neighbor, weight in adj[x]:
            if not visited[neighbor]:
                visited[neighbor] = True
                heapq.heappush(pq, (weight, neighbor))

    return path

edge_list = [
    (0,1,3),(0,2,6),(0,3,5),(1,4,9),(1,5,8),
    (2,6,12),(2,7,14),(3,8,7),(8,9,5),
    (8,10,6),(9,11,1),(9,12,10),(9,13,2)
]
path = best_first_search(edge_list, 0, 9, 14)
print(*path)
```

**Output**
```
0 1 3 2 8 9 
```

**Time Complexity:** O(n * log n), where n is the number of nodes. In the worst case, we may have to visit all nodes before we reach goal. Note that priority queue is implemented using Min (or Max) Heap, and insert and remove operations take O(log n) time.
**Space Complexity:** O(n + e), where n is the number of nodes, and e is the number of edges.

