2. Sort the run using MergeSort.
3. Store the sorted array in a file. Let's say 'i' for ith file.
4. Merge the sorted files using the approach discussed in merge k sorted arrays.

#### Implementation

**C++**
```cpp
// C++ program to implement external sorting using merge sort
#include <bits/stdc++.h>
using namespace std;

struct MinHeapNode {
    int element;  // The element to be stored
    int i;        // index of the array from which the element is taken
};

void swap(MinHeapNode* x, MinHeapNode* y);

class MinHeap {
    MinHeapNode* harr;
    int heap_size;

public:
    MinHeap(MinHeapNode a[], int size);
    void MinHeapify(int);
    int left(int i) { return (2 * i + 1); }
    int right(int i) { return (2 * i + 2); }
    MinHeapNode getMin() { return harr[0]; }
    void replaceMin(MinHeapNode x)
    {
        harr[0] = x;
        MinHeapify(0);
    }
};

MinHeap::MinHeap(MinHeapNode a[], int size)
{
    heap_size = size;
    harr = a;
    int i = (heap_size - 1) / 2;
    while (i >= 0) {
        MinHeapify(i);
        i--;
    }
}

void MinHeap::MinHeapify(int i)
{
    int l = left(i);
    int r = right(i);
    int smallest = i;
    if (l < heap_size && harr[l].element < harr[i].element)
        smallest = l;
    if (r < heap_size && harr[r].element < harr[smallest].element)
        smallest = r;
    if (smallest != i) {
        swap(&harr[i], &harr[smallest]);
        MinHeapify(smallest);
    }
}

void swap(MinHeapNode* x, MinHeapNode* y)
{
    MinHeapNode temp = *x;
    *x = *y;
    *y = temp;
}

void merge(int arr[], int l, int m, int r)
{
    int i, j, k;
    int n1 = m - l + 1;
    int n2 = r - m;
    int L[n1], R[n2];
    for (i = 0; i < n1; i++) L[i] = arr[l + i];
    for (j = 0; j < n2; j++) R[j] = arr[m + 1 + j];
    i = 0; j = 0; k = l;
    while (i < n1 && j < n2) {
        if (L[i] <= R[j]) arr[k++] = L[i++];
        else arr[k++] = R[j++];
    }
    while (i < n1) arr[k++] = L[i++];
    while (j < n2) arr[k++] = R[j++];
}

void mergeSort(int arr[], int l, int r)
{
    if (l < r) {
        int m = l + (r - l) / 2;
        mergeSort(arr, l, m);
        mergeSort(arr, m + 1, r);
        merge(arr, l, m, r);
    }
}

FILE* openFile(char* fileName, char* mode)
{
    FILE* fp = fopen(fileName, mode);
    if (fp == NULL) {
        perror("Error while opening the file.\n");
        exit(EXIT_FAILURE);
    }
    return fp;
}

void mergeFiles(char* output_file, int n, int k)
{
    FILE* in[k];
    for (int i = 0; i < k; i++) {
        char fileName[2];
        snprintf(fileName, sizeof(fileName), "%d", i);
        in[i] = openFile(fileName, "r");
    }
    FILE* out = openFile(output_file, "w");
    MinHeapNode* harr = new MinHeapNode[k];
    int i;
    for (i = 0; i < k; i++) {
        if (fscanf(in[i], "%d ", &harr[i].element) != 1) break;
        harr[i].i = i;
    }
    MinHeap hp(harr, i);
    int count = 0;
    while (count != i) {
        MinHeapNode root = hp.getMin();
        fprintf(out, "%d ", root.element);
        if (fscanf(in[root.i], "%d ", &root.element) != 1) {
            root.element = INT_MAX;
            count++;
        }
        hp.replaceMin(root);
    }
    for (int i = 0; i < k; i++) fclose(in[i]);
    fclose(out);
}

void createInitialRuns(char* input_file, int run_size, int num_ways)
{
    FILE* in = openFile(input_file, "r");
    FILE* out[num_ways];
    char fileName[2];
    for (int i = 0; i < num_ways; i++) {
        snprintf(fileName, sizeof(fileName), "%d", i);
        out[i] = openFile(fileName, "w");
    }
    int* arr = (int*)malloc(run_size * sizeof(int));
    bool more_input = true;
    int next_output_file = 0;
    int i;
    while (more_input) {
        for (i = 0; i < run_size; i++) {
            if (fscanf(in, "%d ", &arr[i]) != 1) {
                more_input = false;
                break;
            }
        }
        mergeSort(arr, 0, i - 1);
        for (int j = 0; j < i; j++)
            fprintf(out[next_output_file], "%d ", arr[j]);
        next_output_file++;
    }
    for (int i = 0; i < num_ways; i++) fclose(out[i]);
    fclose(in);
}

void externalSort(char* input_file, char* output_file, int num_ways, int run_size)
{
    createInitialRuns(input_file, run_size, num_ways);
    mergeFiles(output_file, run_size, num_ways);
}

int main()
{
    int num_ways = 10;
    int run_size = 1000;
    char input_file[] = "input.txt";
    char output_file[] = "output.txt";
    FILE* in = openFile(input_file, "w");
    srand(time(NULL));
    for (int i = 0; i < num_ways * run_size; i++)
        fprintf(in, "%d ", rand());
    fclose(in);
    externalSort(input_file, output_file, num_ways, run_size);
    return 0;
}
```

**Java**
```java
// Java program to implement external sorting using merge sort
import java.io.*;
import java.util.*;

public class ExternalSort {

    static void mergeSort(int[] arr, int l, int r) {
        if (l < r) {
            int m = l + (r - l) / 2;
            mergeSort(arr, l, m);
            mergeSort(arr, m + 1, r);
            merge(arr, l, m, r);
        }
    }

    static void merge(int[] arr, int l, int m, int r) {
        int n1 = m - l + 1, n2 = r - m;
        int[] L = Arrays.copyOfRange(arr, l, l + n1);
        int[] R = Arrays.copyOfRange(arr, m + 1, m + 1 + n2);
        int i = 0, j = 0, k = l;
        while (i < n1 && j < n2)
            arr[k++] = (L[i] <= R[j]) ? L[i++] : R[j++];
        while (i < n1) arr[k++] = L[i++];
        while (j < n2) arr[k++] = R[j++];
    }

    static void createInitialRuns(String inputFile, int runSize, int numWays) throws IOException {
        Scanner sc = new Scanner(new File(inputFile));
        for (int f = 0; f < numWays && sc.hasNextInt(); f++) {
            int[] arr = new int[runSize];
            int i = 0;
            while (i < runSize && sc.hasNextInt()) arr[i++] = sc.nextInt();
            mergeSort(arr, 0, i - 1);
            PrintWriter pw = new PrintWriter(new FileWriter(String.valueOf(f)));
            for (int j = 0; j < i; j++) pw.print(arr[j] + " ");
            pw.close();
        }
        sc.close();
    }

    public static void main(String[] args) throws IOException {
        // Driver: generate input and call external sort
        int numWays = 10, runSize = 1000;
        PrintWriter pw = new PrintWriter("input.txt");
        Random rand = new Random();
        for (int i = 0; i < numWays * runSize; i++) pw.print(rand.nextInt(10000) + " ");
        pw.close();
        createInitialRuns("input.txt", runSize, numWays);
        System.out.println("Initial runs created. Merge step omitted for brevity.");
    }
}
