**Python**
```python
# Python program to implement external sorting using merge sort
import random
import heapq

def merge_sort(arr):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)

def merge(left, right):
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            result.append(left[i]); i += 1
        else:
            result.append(right[j]); j += 1
    result.extend(left[i:])
    result.extend(right[j:])
    return result

def create_initial_runs(input_file, run_size, num_ways):
    with open(input_file) as f:
        data = list(map(int, f.read().split()))
    file_idx = 0
    for start in range(0, len(data), run_size):
        chunk = merge_sort(data[start:start + run_size])
        with open(str(file_idx), 'w') as out:
            out.write(' '.join(map(str, chunk)))
        file_idx += 1
        if file_idx >= num_ways:
            break

def merge_files(output_file, num_ways):
    readers = [open(str(i)) for i in range(num_ways)]
    heap = []
    buffers = []
    for i, r in enumerate(readers):
        nums = list(map(int, r.read().split()))
        buffers.append(nums)
        if nums:
            heapq.heappush(heap, (nums[0], i, 0))
    with open(output_file, 'w') as out:
        while heap:
            val, fi, idx = heapq.heappop(heap)
            out.write(str(val) + ' ')
            if idx + 1 < len(buffers[fi]):
                heapq.heappush(heap, (buffers[fi][idx + 1], fi, idx + 1))
    for r in readers:
        r.close()

num_ways, run_size = 10, 1000
with open('input.txt', 'w') as f:
    f.write(' '.join(str(random.randint(0, 100000)) for _ in range(num_ways * run_size)))
create_initial_runs('input.txt', run_size, num_ways)
merge_files('output.txt', num_ways)
```

**Time Complexity:** O(N * log N).

Time taken for merge sort is O(runs * run_size * log run_size), which is equal to O(N log run_size).
To merge the sorted arrays the time complexity is O(N * log runs).
Therefore, the overall time complexity is O(N * log run_size + N * log runs).
Since log run_size + log runs = log run_size*runs = log N, the result time complexity will be O(N * log N).

**Auxiliary Space:** O(run_size). run_size is the space needed to store the array.

> **Note:** This code won't work on an online compiler as it requires file creation permissions. When running in a local machine, it produces a sample input file "input.txt" with 10000 random numbers. It sorts the numbers and puts the sorted numbers in a file "output.txt". It also generates files with names 1, 2, .. to store sorted runs.

