    cnt = [0] * (maxval + 1)
    for x in arr: cnt[x] += 1
    for i in range(1, maxval + 1): cnt[i] += cnt[i - 1]
    ans = [0] * len(arr)
    for x in reversed(arr):
        ans[cnt[x] - 1] = x
        cnt[x] -= 1
