    constructor() {
        this.arr = [];
    }

    // push operation
    push(x) {
        this.arr.push(x);
    }

    // pop operation
    pop() {
        if (this.arr.length === 0) {
            console.log("Stack Underflow");
            return -1;
        }
        return this.arr.pop();
    }

    // peek operation
    peek() {
        if (this.arr.length === 0) {
            console.log("Stack is Empty");
            return -1;
        }
        return this.arr[this.arr.length - 1];
    }

    // check if stack is empty
    isEmpty() {
        return this.arr.length === 0;
    }

    // current size
    size() {
        return this.arr.length;
    }
}

// Driver Code
