void customRemoveCharAtPosition(string &s, int pos) {

    if (pos < 0 || pos >= s.length()) {
        return; 
    }

    // Shift characters to the left from the position
    for (int i = pos; i < s.length() - 1; i++) {
        s[i] = s[i + 1];
    }

    s.resize(s.length() - 1);
}

