    // the middle of the string
    while (left < right) {
        char temp = s[left];
        s[left] = s[right];
        s[right] = temp;
        left++;
        right--;
    }

    return s;
}

int main() {
    char s[] = "abdcfe"; 
    printf("%s", reverseString(s)); 
    return 0;
}
```

