    // Swap the characters at the ends
    char temp = s[l];
    s[l] = s[r];
    s[r] = temp;

    // Recur for the remaining string
    reverseStringRec(s, l + 1, r - 1);
}

char* reverseString(char *s) {
    int n = strlen(s);
    reverseStringRec(s, 0, n - 1);
  	return s;
}

int main() {
    char s[] = "abdcfe";

    printf("%s\n", reverseString(s));
    return 0;
}
